package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OptionsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property options of observed panel ")
  void test_options_v_o_builder() {
    Assertions.assertFalse(OptionsVO.nullValue().getOptions().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(OptionsVO.tryFrom(null).getOptions().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", OptionsVO.from("one").getOptions().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> OptionsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OptionsVO.from("one").toString());
  }
}
